**CLI Command Signatures (citty):**

```typescript
// src/cli/commands/users/index.ts
export default defineCommand({
  meta: { name: 'users', description: 'Manage users' },
  subCommands: {
    list: () => import('./list'),
    get: () => import('./get'),
    create: () => import('./create'),
    update: () => import('./update'),
    delete: () => import('./delete'),
    'reset-password': () => import('./reset-password'),
    credentials: () => import('./credentials')
  }
});

// src/cli/commands/users/list.ts
export default defineCommand({
  meta: { name: 'list', description: 'List users' },
  args: {
    search: { type: 'string', alias: 's', description: 'Search query' },
    max: { type: 'string', alias: 'm', description: 'Max results' },
    json: { type: 'boolean', alias: 'j', description: 'Output as JSON' }
  },
  async run({ args }) {
    const userService = await getUserService();
    const users = await userService.list({ 
      search: args.search, 
      max: args.max ? parseInt(args.max) : undefined 
    });
    if (args.json) {
      printJson(users);
    } else {
      printTable(users, ['id', 'username', 'email', 'enabled']);
    }
  }
});
```

