export function printTable<T>(data: T[], columns: Array<keyof T>): void;
export function printJson<T>(data: T): void;
export function printError(error: IdentiKeyError | Error): void;
```

**Expected CLI Behavior:**

```bash
kc users list
# Output: ASCII table with id, username, email, enabled columns

kc users list --json
# Output: JSON array of User objects

kc users get <id>
# Output: Full user details (all fields)

kc users create --username john --email john@example.com
# Output: Created user confirmation

kc users delete <id>
# Prompt: "Delete user <username>? (y/n)" 
# Output: "User deleted" or "Cancelled"

kc users reset-password <id>
# Prompt: "New password:" (no echo)
# Output: "Password reset successfully"
```
